def ladybug_to_proto(type_name: NodeType | RelType, row: dict[str, object]) -> dict[str, object]:
    """Remap LadybugDB column names to protobuf field names.

    Use this when reading a row from the database and converting it to a
    protobuf message via ``ParseDict``. Only columns with a ``(ladybug.column)``
    override are remapped; all other keys pass through unchanged. Returns the
    input unchanged for types with no remapped columns.

    Example::

        row = {"id": "s1", "name": "api", "repoUrl": "https://..."}
        msg = ParseDict(ladybug_to_proto("Service", row), ServiceNode())
    """
    mapping = _COLUMN_TO_PROTO.get(type_name)
    if not mapping:
        return row
    return {mapping.get(k, k): v for k, v in row.items()}


def proto_to_ladybug(type_name: NodeType | RelType, obj: dict[str, object]) -> dict[str, object]:
    """Remap protobuf field names to LadybugDB column names.

    Use this when converting a protobuf message (or its dict representation)
    to a row suitable for writing to the database. Only fields with a
    ``(ladybug.column)`` override are remapped; all other keys pass through
    unchanged. Returns the input unchanged for types with no remapped columns.

    Example::

        obj = MessageToDict(msg, preserving_proto_field_name=True)
        row = proto_to_ladybug("Service", obj)
        # {"id": "s1", "name": "api", "repoUrl": "https://..."}
    """
    mapping = _PROTO_TO_COLUMN.get(type_name)
    if not mapping:
        return obj
    return {mapping.get(k, k): v for k, v in obj.items()}
